using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "LunarAlignmentPreviewDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/PreviewDescription/Moonie/LunarAlignmentPreviewDescription", order = 0)]
public class LunarAlignmentPreviewDescription : PreviewDescription
{
	public override int GetPreviewAmount(string amountModified, BattleAction battleAction)
	{
		return (battleAction as LunarAlignmentAction).GetPurifyAmount(GetAmountWithoutEquation(amountModified));
	}
}
